import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Typechecker in Handl","description":"","frontmatter":{"title":"Typechecker in Handl","type":"adr","date":"2026-09-10T00:00:00.000Z","status":"accepted","status_note":"Accepted — the typechecker models live in handl; Rust keeps the engine."},"headers":[],"relativePath":"handl/project/adrs/0105-typechecker-in-handl.md","filePath":"vendored/handl/project/adrs/0105-typechecker-in-handl.md"}`),a={name:`handl/project/adrs/0105-typechecker-in-handl.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0105-typechecker-in-handl" tabindex="-1">ADR-0105: Typechecker in Handl <a class="header-anchor" href="#adr-0105-typechecker-in-handl" aria-label="Permalink to “ADR-0105: Typechecker in Handl”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>The typechecker&#39;s models are handl</strong>; Rust keeps only the engine/driver.</li><li><strong>What stays in Rust</strong>: the engine, VM primitives and the adapter that loads the model.</li><li><strong>What moves to handl</strong>: the type model (judgment ops) plus the scope and totality models.</li><li><strong>Bootstrap</strong>: Rust embeds the <code>.hnl</code> model with <code>include_str!</code>, loads it into a <code>HandlModule</code>, and calls its <code>typecheck</code> function.</li><li><strong>The adapter is thin</strong> — the model is the implementation, not a wrapper.</li><li><strong>Parity is proven against the Rust model</strong> by the existing type-model tests.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The typechecker was the last stage with its semantics in Rust, so a language change meant an engine change and the rules could not be inspected. A handl model plus a thin adapter keeps the engine generic and makes typing data.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep the typechecker in Rust</strong> — the last stage outside language-as-data.</li><li><strong>Embed the model as a Rust port</strong> — the <code>.hnl</code> source is embedded and loaded.</li><li><strong>A fat adapter</strong> — it only loads and calls.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The type model is handl; the engine is generic.</li><li>Bootstrap depends on <code>include_str!</code> + <code>HandlModule</code>; no separate install step.</li><li>Parity tests gate the switch.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>project/design/adr0103/typecheck_model.hnl</code>, <code>scope_model.hnl</code>, <code>totality_model.hnl</code>.</li><li><code>engine-typecheck-nbe</code> — the engine + adapter.</li><li>Type-model parity tests.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+Architecture, Rust/handl boundary, bootstrap and the model suite: +<a href="./../design/0105-typechecker-in-handl.html"><code>design/0105-typechecker-in-handl.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};